} from "./date_utils";

const VERTICAL_NAVIGATION_OFFSET = 3;

interface YearProps extends Pick<
  DateFilterOptionsWithDisabled,
  | "minDate"
  | "maxDate"
  | "excludeDates"
  | "includeDates"
  | "filterDate"
  | "disabled"
