      ...props.popperProps,
    });

    const componentProps = {
      ...props,
      hidePopper,
      popperProps: { ...floatingProps, arrowRef },
    } as unknown as T;

    return <Component {...componentProps} />;
  }

  WithFloating.displayName = `withFloating(${Component.displayName || Component.name || "Component"})`;

  return WithFloating;
